import React, { forwardRef, type ReactNode } from 'react'
import type { EventPayload } from '@gpuix/react'
import { useTheme, type Style } from '@gpuix-ui/core'
import { useControllableState, type DivProps, type Instance } from '@gpuix-ui/primitives'
import { asText } from './internal'

export interface ToggleProps extends Omit<DivProps, 'style' | 'children'> {
  pressed?: boolean
  defaultPressed?: boolean
  onPressedChange?: (pressed: boolean) => void
  disabled?: boolean
  variant?: 'default' | 'outline'
  size?: 'sm' | 'md'
  style?: Style
  children?: ReactNode
}

export const Toggle = forwardRef<Instance, ToggleProps>(function Toggle(
  { pressed: pressedProp, defaultPressed = false, onPressedChange, disabled = false, variant = 'default', size = 'md', style, children, onClick, onKeyDown, ...props },
  ref,
) {
  const t = useTheme()
  const [pressed, setPressed] = useControllableState({ value: pressedProp, defaultValue: defaultPressed, onChange: onPressedChange })
  const toggle = () => !disabled && setPressed(!pressed)
  return (
    <div
      {...props}
      ref={ref}
      tabIndex={disabled ? -1 : (props.tabIndex ?? 0)}
      style={{
        display: 'flex',
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 6,
        height: size === 'sm' ? 32 : 36,
        paddingLeft: size === 'sm' ? 8 : 12,
        paddingRight: size === 'sm' ? 8 : 12,
        borderRadius: t.radius.md,
        borderWidth: 1,
        borderColor: variant === 'outline' ? t.colors.input : '#00000000',
        backgroundColor: pressed ? t.colors.accent : '#00000000',
        cursor: disabled ? 'default' : 'pointer',
        opacity: disabled ? 0.5 : 1,
        userSelect: 'none',
        hover: disabled ? undefined : { backgroundColor: pressed ? t.colors.accent : t.colors.overlay },
        ...style,
      }}
      onClick={(event) => {
        onClick?.(event)
        toggle()
      }}
      onKeyDown={(event: EventPayload) => {
        onKeyDown?.(event)
        if (event.key === 'enter' || event.key === 'space') toggle()
      }}
    >
      {asText(children, { fontFamily: t.font.sans, fontSize: t.font.size.sm, fontWeight: 500, color: pressed ? t.colors.accentForeground : t.colors.foreground })}
    </div>
  )
})

/** Helpers shared by the styled components. */
import React, { useState, type ReactNode } from 'react'
import type { EventPayload } from '@gpuix/react'
import type { Style } from '@gpuix-ui/core'

/**
 * GPUI does not inherit `color`, so a bare string child would paint black.
 * Wrap string and number children in a `<text>` carrying the given style;
 * pass elements through untouched.
 */
export function asText(children: ReactNode, style: Style): ReactNode {
  if (children == null || typeof children === 'boolean') return null
  if (typeof children === 'string' || typeof children === 'number') return <text style={style}>{String(children)}</text>
  if (Array.isArray(children)) {
    if (children.every((child) => typeof child === 'string' || typeof child === 'number')) return <text style={style}>{children.join('')}</text>
    // Mixed children, like an icon next to a label: wrap just the strings.
    return children.map((child, index) =>
      typeof child === 'string' || typeof child === 'number' ? (
        <text key={`text-${index}`} style={style}>
          {String(child)}
        </text>
      ) : (
        child
      ),
    )
  }
  return children
}

/** Track native focus on an element, for a focus ring. */
export function useFocusState(handlers: { onFocus?: (event: EventPayload) => void; onBlur?: (event: EventPayload) => void } = {}) {
  const [focused, setFocused] = useState(false)
  return {
    focused,
    onFocus: (event: EventPayload) => {
      handlers.onFocus?.(event)
      setFocused(true)
    },
    onBlur: (event: EventPayload) => {
      handlers.onBlur?.(event)
      setFocused(false)
    },
  }
}

/** Track hover in React state, for components that render different children on hover. */
export function useHoverState() {
  const [hovered, setHovered] = useState(false)
  return { hovered, onMouseEnter: () => setHovered(true), onMouseLeave: () => setHovered(false) }
}
